-- las-aventuras-de-tom-sawyer -- PARTE 5 de 5. Ejecuta las partes EN ORDEN.

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  80,
  'Perdidos en la cueva (3/4)',
  $lira$[{"type": "p", "text": "—No hable usted de ello, señora. Hay alguien con quien tal vez esté más en deuda que conmigo y mis hijos, pero no quiere que diga su nombre. A no ser por él, no habríamos acudido."}, {"type": "p", "text": "Aquellas palabras, por supuesto, excitaron una curiosidad tan intensa que casi empequeñeció el hecho principal, pero el galés dejó que la curiosidad picara a sus visitantes, y que a través de ellos se transmitiese a todo el pueblo, pues él se negó a revelar su secreto. Cuando se supieron los demás detalles, la viuda dijo:"}, {"type": "p", "text": "—Estaba leyendo en la cama y me quedé dormida. El alboroto no me despertó. ¿Por qué no vino usted?"}, {"type": "p", "text": "—Consideramos que no valía la pena. No era probable que aquellos bribones volviesen; no tenían herramientas con que trabajar, y ¿qué necesidad había de despertarla y darle un susto de muerte? Mis tres negros se quedaron de guardia en su casa toda la noche. Ahora acaban de regresar."}, {"type": "p", "text": "El galés tuvo que contar la historia una y otra vez durante un par de horas más a medida que llegaban nuevas visitas."}, {"type": "p", "text": "Durante las vacaciones escolares no había escuela dominical, pero todo el mundo acudió temprano a la iglesia. Se comentó con detalle el sensacional acontecimiento. Llegaron noticias de que aún no se había descubierto ni rastro de los dos malhechores. Cuando terminó el sermón, la esposa del juez Thatcher se acercó a la señora Harper mientras recorría el pasillo entre la multitud y dijo:"}, {"type": "p", "text": "—¿Mi Becky va a dormir todo el día? Ya sabía yo que estaría muerta de cansancio."}, {"type": "p", "text": "—¿Becky?"}, {"type": "p", "text": "—Sí —dijo la señora Thatcher con una expresión de asombro—, ¿no ha pasado la noche en su casa?"}, {"type": "p", "text": "—¿En mi casa? No."}, {"type": "p", "text": "La señora Thatcher palideció y se dejó caer sobre un banco en el momento en que pasaba la tía Polly, hablando animadamente con una amiga."}, {"type": "p", "text": "—Buenos días, señora Thatcher. Buenos días, señora Harper —dijo la tía Polly—. Resulta que uno de mis chicos no volvió a dormir a casa. Supongo que Tom habrá pasado la noche en casa de alguna de ustedes, y ahora debe de tener miedo de venir a la iglesia. Ya le ajustaré las cuentas. La señora Thatcher negó con la cabeza y su palidez se acrecentó."}, {"type": "p", "text": "—En casa no ha estado —dijo la señora Harper, comenzando a mostrar cierta inquietud. Una marcada ansiedad se pintó en el rostro de la tía Polly."}, {"type": "p", "text": "—Joe Harper, ¿has visto a mi Tom esta mañana?"}, {"type": "p", "text": "—No, señora."}, {"type": "p", "text": "—¿Cuándo lo viste por última vez?"}, {"type": "p", "text": "Joe intentó acordarse, pero no estaba seguro de cuándo fue. La gente se había quedado parada en la iglesia. Corrió la voz de lo que ocurría y en todos los rostros se reflejó una expresión de inquietud. Los niños y los jóvenes maestros fueron interrogados con ansia. Todos dijeron que no habían observado si Tom y Becky se encontraban a bordo del vapor durante el viaje de retorno; estaba oscuro; a nadie se le había ocurrido preguntar si faltaba alguien. Por último, un joven declaró abruptamente sus temores de que se hallasen todavía en la cueva. La señora Thatcher se desmayó. La tía Polly rompió a llorar retorciéndose las manos."}, {"type": "p", "text": "Corrió la alarma de boca en boca, de grupo en grupo, de calle en calle, y al cabo de cinco minutos las campanas tañían furiosamente y todo el pueblo estaba en pie."}, {"type": "p", "text": "El episodio de Cardiff se volvió insignificante al instante, se olvidaron de los ladrones, ensillaron caballos, aparejaron botes, ordenaron la salida del vapor, y al cabo de media hora doscientos hombres se desparramaban por la calle principal y por el río en dirección a la cueva."}, {"type": "p", "text": "El pueblo dio la impresión de estar vacío y muerto durante toda la tarde. Muchas mujeres visitaron a la tía Polly y a la señora Thatcher y trataron de consolarlas. Unieron también su llanto al de ellas, y aquello fue mejor aún que las palabras. Durante el lento transcurso de la noche el pueblo esperó noticias; pero cuando al final clareó, la única nueva que llegó fue: «Enviad más velas y comida». La señora Thatcher estaba casi loca, al igual que la tía Polly. El juez Thatcher envió mensajes desde la cueva dando esperanzas, pero no procuraron ningún consuelo."}, {"type": "p", "text": "El viejo galés volvió a su casa al clarear el día, salpicado de sebo de vela, manchado de arcilla y casi sin fuerzas. Encontró a Huck todavía en la cama que le había prestado, delirando de fiebre. Los médicos estaban todos en la cueva, de modo que llamó a la viuda Douglas, que tomó el paciente a su cargo. Dijo que le cuidaría lo mejor que sabía, porque tanto si era un chico bueno, malo o indiferente, era una criatura del Señor, y nada que fuese del Señor podía desecharse. El galés dijo que Huck tenía buen fondo, y la viuda contestó:"}]$lira$::jsonb,
  805
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  81,
  'Perdidos en la cueva (4/4)',
  $lira$[{"type": "p", "text": "—No lo pongo en duda. Esa es la marca del Señor. No la olvida. No la olvida nunca. La pone en cualquier criatura que viene de Sus manos."}, {"type": "p", "text": "A mediodía algunos grupos de hombres exhaustos volvieron al pueblo, pero los ciudadanos más fuertes continuaron buscando. Las noticias más halagüeñas que llegaron fueron que estaban escudriñando remotos lugares de la cueva que nunca se habían visitado; que se buscaba en cada rincón y en cada grieta; que dondequiera que uno vagase, a través de la confusión de pasadizos, veía fluctuar luces a un lado y a otro en la distancia, y que los gritos y los disparos de pistola enviaban al oído sus huecas resonancias desde las sombrías naves. En un lugar alejado de la sección que solían frecuentar los turistas habían hallado los nombres «BECKY & TOM» trazados en la pared de piedra con humo de vela, y no lejos de allí un trozo de cinta manchada de sebo. La señora Thatcher reconoció la cinta y derramó lágrimas sobre ella. Dijo que era la última reliquia que tendría de su hijita, y que ningún otro recuerdo suyo sería tan precioso, porque ese era el último que se separó del cuerpo en vida antes de que llegara la pavorosa muerte. Alguien dijo que de vez en cuando en la cueva parpadeaba un lejano fulgor, y entonces resonaba un clamor de triunfo y una veintena de hombres se precipitaba por el pasadizo lleno de ecos… y el resultado era siempre una abrumadora decepción: los niños no estaban allí, no era más que la luz de otro buscador. Tres días y tres noches horribles arrastraron sus horas tediosas, mientras el pueblo se hundía en un desesperado estupor. Nadie tenía ánimos para nada. El reciente descubrimiento de que el propietario de la taberna guardaba bebidas alcohólicas en su establecimiento apenas alteró el ánimo del público, por tremendo que fuese el hecho. En un momento de lucidez, Huck llevó la conversación al tema de las tabernas, y preguntó por último —temiendo casi lo peor— si se había descubierto algo en la taberna desde que estaba en cama."}, {"type": "p", "text": "—¡Sí! —dijo la viuda."}, {"type": "p", "text": "Huck dio un respingo en la cama y miró a la viuda con ojos extraviados."}, {"type": "p", "text": "—¿Qué? ¿Qué era?"}, {"type": "p", "text": "—Alcohol, y han cerrado el establecimiento. Acuéstate, niño, ¡qué susto me has dado!"}, {"type": "p", "text": "—Dígame solo una cosa; solo una, por favor, ¿fue Tom Sawyer quien lo descubrió?"}, {"type": "p", "text": "La viuda se echó a llorar."}, {"type": "p", "text": "—Calma, niño, calma. Ya te he dicho que no debes hablar. Estás muy enfermo."}, {"type": "p", "text": "Así que no se había encontrado más que alcohol; de haber sido oro, habría causado un gran alboroto. De modo que el tesoro había desaparecido para siempre, ¡para siempre! Pero ¿por qué lloraba la viuda? Era curioso que llorara."}, {"type": "p", "text": "Esos pensamientos se abrían paso lentamente en el cerebro de Huck, que se durmió por el cansancio que le provocaron. La viuda se dijo para sí:"}, {"type": "p", "text": "—Ya se ha dormido, pobrecillo. ¡Que si lo encontró Tom Sawyer! ¡Lo malo es que nadie lo encuentre a él! ¡Ay, qué pocos tienen aún esperanzas o fuerzas para seguir buscando!"}]$lira$::jsonb,
  517
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  82,
  'Hallados y perdidos de nuevo (1/4)',
  $lira$[{"type": "p", "text": "Veamos ahora qué les ocurrió a Tom y Becky durante el picnic. Recorrieron los sombríos pasadizos con los demás compañeros, visitando las maravillas conocidas de la cueva, maravillas dignificadas con nombres tan descriptivos como «el vestíbulo», «la catedral», «el palacio de Aladino» y otros por el estilo. Al cabo de poco comenzaron a jugar al escondite, y Tom y Becky participaron en el juego con entusiasmo hasta que el esfuerzo comenzó a resultar algo aburrido; entonces bajaron por una sinuosa avenida, con las velas en alto y leyendo la embrollada telaraña de nombres, fechas, direcciones y epígrafes con que se habían decorado (con humo de vela) las rocosas paredes. Caminando y charlando, apenas observaron que se hallaban en una parte de la cueva cuyos muros no estaban decorados. Escribieron sus propios nombres con humo bajo un saliente de roca y prosiguieron la marcha. Pronto llegaron a un lugar en que un arroyuelo, al escurrirse sobre uno de los bordes y llevar un sedimento de piedra caliza, había formado, con el lento transcurso de los siglos, una catarata como la del Niágara de rizos y encajes en la piedra resplandeciente e imperecedera. Tom deslizó su cuerpecillo por detrás de la cascada para iluminarla, con la consiguiente satisfacción de Becky. Vio entonces que el agua encubría una especie de abrupta escalera natural encerrada entre estrechos muros, y al instante se apoderó de él la ambición de hacer un descubrimiento. Becky respondió a su invitación, hicieron una marca con humo para guiarse más tarde, y emprendieron las pesquisas. Serpentearon por un camino y otro, adentráronse en las secretas profundidades de la cueva, hicieron otra marca, y tomaron un pasadizo lateral en busca de novedades que contar después a los compañeros. En un lugar encontraron una espaciosa caverna, de cuyo techo pendían multitud de brillantes estalactitas de la longitud y el diámetro de la pierna de un hombre; la recorrieron admirándola maravillados, y poco después tomaron uno de los numerosos pasadizos que desembocaban en ella. Aquel corredor los llevó enseguida a una encantadora fuente, cuyo pilón estaba incrustado de una escarcha de chispeantes cristales; se hallaba en medio de una caverna que sostenían innumerables y fantásticos pilares formados por la unión de grandes estalactitas y estalagmitas, resultado del incesante gotear del agua a lo largo de los siglos. Bajo el techo se habían apiñado vastos conjuntos de murciélagos, miles en cada grupo; las luces turbaron a los animalejos y se precipitaron a cientos contra las velas, chillando y aleteando furiosamente."}, {"type": "p", "text": "Tom conocía sus métodos y el peligro que estos encerraban. Cogió a Becky de la mano y la precipitó en el primer corredor que vieron, pero no fue lo bastante rápido, pues un murciélago apagó la vela de Becky de un aletazo en el momento de abandonar la caverna. Los murciélagos persiguieron a los niños durante un buen trecho, pero los fugitivos entraban en cada nuevo pasadizo que aparecía, y al final consiguieron librarse de los peligrosos animales. Al cabo de poco Tom encontró un lago subterráneo que extendía su opaca longitud hasta que su forma se perdía en las sombras. Quería explorar las orillas, pero decidió que sería mejor sentarse primero y descansar un rato. Entonces, por vez primera, la honda quietud del lugar apoyó su mano viscosa en los espíritus de los niños."}, {"type": "p", "text": "—No me había dado cuenta, pero me parece que hace muchísimo tiempo que no oigo a ninguno de los otros —dijo Becky."}, {"type": "p", "text": "—Ten en cuenta, Becky, que estamos mucho más abajo que ellos, y no sé si más al norte, al sur o al oeste. Desde aquí no podemos oírlos."}, {"type": "p", "text": "Becky mostró cierta aprensión."}, {"type": "p", "text": "—¿Cuánto hace que estamos aquí, Tom? Creo que sería mejor regresar."}, {"type": "p", "text": "—Sí, tal vez sea lo mejor."}, {"type": "p", "text": "—¿Sabrás encontrar el camino, Tom? Para mí es un embrollo con tantas vueltas y revueltas."}, {"type": "p", "text": "—Supongo que podría encontrarlo, pero hay murciélagos. Si nos apagan las dos velas, estaremos en un terrible aprieto. Intentemos encontrar algún otro camino para no tener que pasar por allí."}, {"type": "p", "text": "—Espero que no nos perdamos. ¡Sería espantoso! —Y la muchacha se estremeció al pensar en aquellas horribles posibilidades."}, {"type": "p", "text": "Emprendieron el camino de vuelta por el corredor y recorrieron en silencio un buen trecho, observando cada nueva abertura para ver si su aspecto les resultaba familiar. Por desgracia, todas eran desconocidas. Cada vez que Tom inspeccionaba un corredor, Becky le observaba el rostro en busca de algún signo animoso, y él decía alegremente:"}]$lira$::jsonb,
  739
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  83,
  'Hallados y perdidos de nuevo (2/4)',
  $lira$[{"type": "p", "text": "—No, no es este, pero ya lo encontraremos pronto. No te preocupes."}, {"type": "p", "text": "Ante cada nuevo fracaso se sentía más desalentado y enseguida comenzaron a penetrar en pasadizos divergentes, a la ventura, confiando desesperadamente en hallar el que buscaban. Tom seguía diciendo que «lo encontrarían pronto», pero el temor pesaba como un plomo en su corazón y sus palabras habían perdido su tono esperanzado. Era como si dijera: «¡Todo está perdido!». Becky no se movía de su lado angustiada por el miedo y trataba con todas sus fuerzas de retener las lágrimas, pero era inútil."}, {"type": "p", "text": "—Ay, Tom, no me importan los murciélagos, volvamos por aquel camino. Cada vez me parece que nos perdemos más —dijo al fin."}, {"type": "p", "text": "—¡Escucha! —dijo Tom deteniéndose."}, {"type": "p", "text": "Reinaba un silencio tan profundo que sus respiraciones eran audibles en aquella quietud. Tom gritó. La llamada repercutió por las naves vacías y murió en la distancia, en un sonido leve parecido al cabrilleo de una risa burlona."}, {"type": "p", "text": "—No vuelvas a llamar, Tom, es horrible —dijo Becky."}, {"type": "p", "text": "—Es horrible, pero es mejor hacerlo, Becky; tal vez nos oigan, ¿sabes? —y gritó de nuevo. Aquel «tal vez» era de una frialdad más horrible aún que la risa espectral, pues confesaba que había perdido la esperanza. Los niños se quedaron quietos escuchando, pero no oyeron respuesta alguna. Tom volvió sobre sus pasos apresuradamente. No transcurrió mucho tiempo sin que cierta indecisión en sus maneras revelara a Becky otro hecho espantoso: no podía encontrar el camino de vuelta."}, {"type": "p", "text": "—¡Ay, Tom! No has hecho ninguna señal."}, {"type": "p", "text": "—¡He sido un estúpido, Becky! ¡Un estúpido! No pensaba que fuéramos a volver por el mismo camino. No, no encuentro el camino. Todo es confuso."}, {"type": "p", "text": "—Tom, Tom, estamos perdidos. No saldremos jamás de este horrible lugar. ¿Por qué hemos abandonado a los otros?"}, {"type": "p", "text": "Se dejó caer al suelo y rompió en un llanto tan desesperado que a Tom le aterró la idea de que pudiese morir o perder la razón. Se sentó a su lado y la rodeó con los brazos; ella hundió su cabecita en el pecho de Tom, se abrazó a él, se liberó de sus terrores y de sus lamentos inútiles, y los ecos lejanos convirtieron sus palabras en risas burlonas. Tom le suplicó que tuviese valor, pero ella dijo que no podía. Tom comenzó a reprocharse y a insultarse por haberla llevado a una situación tan penosa; aquello resultó más efectivo. Becky dijo que intentaría recobrar las esperanzas e iría a dondequiera que él la llevase, con tal que no hablara otra vez de aquel modo. Al fin y al cabo, no merecía ella menos reproches que él, agregó. Retomaron el camino sin rumbo; lo único que podían hacer era seguir adelante. Durante un rato sus esperanzas revivieron, no porque hubiese razón para ello, sino porque está en su naturaleza revivir cuando el manantial no está agostado por los años y la familiaridad con el fracaso."}, {"type": "p", "text": "Al cabo de poco Tom cogió la vela de Becky y la apagó. ¡Ese ahorro significaba mucho! No hacían falta palabras. Becky comprendió la triste realidad y sus esperanzas murieron de nuevo. Sabía que Tom tenía una vela entera y tres o cuatro pedazos en los bolsillos, pero era preciso ahorrar. Entretanto, la fatiga comenzaba a reclamar sus derechos; los niños trataron de no prestarle atención, pues era horrible pensar en sentarse cuando el tiempo se había convertido en algo tan precioso; al menos caminar en alguna dirección, en cualquier dirección, era un progreso que podía dar sus frutos, pero sentarse era invitar a la muerte y acortar su persecución."}, {"type": "p", "text": "Al final las frágiles piernas de Becky se negaron a llevarla más lejos. Se sentó. Tom se quedó con ella, y hablaron de sus familias, de los amigos, de los lechos confortables y, sobre todo, de la luz. Becky se puso a llorar, y Tom intentó pensar en alguna manera de consolarla, pero todas sus palabras de ánimo estaban manidas y parecían sarcasmos. La fatiga se apoderó tanto de Becky que se durmió. Tom se alegró. Se puso a contemplar su carita tensa y vio que se suavizaba y volvía a su expresión natural bajo la influencia de agradables sueños, y poco después le brotó una sonrisa. Aquel rostro sosegado transmitió un poco de paz y de balsámica quietud a su propio espíritu, y sus pensamientos vagaron hacia tiempos pasados y brumosos recuerdos. Mientras estaba sumido en sus cavilaciones, Becky se despertó con una fresca risa, pero se le murió en los labios y fue seguida de un gemido."}]$lira$::jsonb,
  751
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  84,
  'Hallados y perdidos de nuevo (3/4)',
  $lira$[{"type": "p", "text": "—¿Cómo he podido dormirme? ¡Ojalá no me hubiese despertado nunca! ¡No, no quiero decir eso, Tom! No me mires así. No volveré a decirlo."}, {"type": "p", "text": "—Me alegro de que hayas dormido, Becky; ahora te sentirás más descansada y encontraremos el camino de salida."}, {"type": "p", "text": "—Intentémoslo, Tom, pero en sueños he visto un país bellísimo y creo que vamos allí."}, {"type": "p", "text": "—Puede que no, puede que no. Anímate, Becky, y sigamos probando."}, {"type": "p", "text": "Prosiguieron la marcha, cogidos de la mano y poseídos por un profundo desaliento. Intentaron calcular cuánto tiempo hacía que estaban en la cueva, pero solo llegaron a la conclusión de que podía hacer varios días o semanas. No obstante, era imposible, pues las velas aún no se habían consumido. Un buen rato después —no podían decir cuánto— Tom dijo que tenían que andar con suavidad para oír el goteo del agua; era preciso que hallasen una fuente. Pronto encontraron una, y Tom dijo que era hora de volver a descansar. Estaban muy fatigados, pero Becky insistió en seguir adelante. Le sorprendió que Tom se negara. Se sentaron y Tom fijó la vela en la pared de enfrente con un poco de arcilla. Tenía el pensamiento ocupado; durante un rato no dijeron nada, pero Becky rompió el silencio:"}, {"type": "p", "text": "—Tom, estoy muy hambrienta."}, {"type": "p", "text": "Tom sacó algo del bolsillo."}, {"type": "p", "text": "—¿Lo recuerdas? —preguntó."}, {"type": "p", "text": "Becky casi sonrió."}, {"type": "p", "text": "—Es nuestro pastel de bodas, Tom."}, {"type": "p", "text": "—Sí, ¡ojalá fuese del tamaño de un barril! ¡Es lo único que tenemos!"}, {"type": "p", "text": "—Lo separé de la merienda para que pudiésemos soñar con él, Tom, como hacen las personas mayores con los pasteles de boda, pero será nuestro…"}, {"type": "p", "text": "Se interrumpió y dejó la frase sin concluir. Tom dividió el pastel y Becky comió con apetito, mientras Tom mordisqueaba su mitad. Allí había abundante agua fresca para terminar el banquete. Luego Becky sugirió continuar adelante. Tom guardó un momento de silencio y luego dijo:"}, {"type": "p", "text": "—Becky, ¿podrás soportar que te diga una cosa?"}, {"type": "p", "text": "El rostro de Becky palideció, pero dijo que sí."}, {"type": "p", "text": "—Oye, Becky, tenemos que quedarnos aquí, donde hay agua para beber. Solo nos queda ese trocito de vela."}, {"type": "p", "text": "Becky dio rienda suelta a sus lágrimas y a su dolor. Tom procuró consolarla, pero en vano."}, {"type": "p", "text": "—¡Tom! —exclamó Becky al fin."}, {"type": "p", "text": "—¿Qué, Becky?"}, {"type": "p", "text": "—Nos echarán de menos y nos buscarán."}, {"type": "p", "text": "—Claro que sí. Por supuesto que sí."}, {"type": "p", "text": "—Tal vez ya nos están buscando, Tom."}, {"type": "p", "text": "—¡Ojalá!"}, {"type": "p", "text": "—¿Cuándo nos echarían en falta, Tom?"}, {"type": "p", "text": "—Supongo que al regresar al vapor."}, {"type": "p", "text": "—Tom, entonces ya debía de haber oscurecido; ¿se darían cuenta de que no habíamos vuelto?"}, {"type": "p", "text": "—No lo sé. Pero, de todos modos, tu mamá te echaría de menos cuando volvieran los demás. La expresión de terror que se pintó en el rostro de Becky hizo comprender a Tom que había cometido un desatino. ¡Aquella noche Becky no tenía que volver a su casa! Los niños se quedaron silenciosos y pensativos. Un momento después, una nueva explosión de dolor por parte de Becky demostró a Tom que la idea que tenía en la cabeza se le había ocurrido también a la muchacha: que podía muy bien transcurrir media mañana del domingo antes de que la señora Thatcher descubriera que Becky no había dormido en casa de la señora Harper."}, {"type": "p", "text": "Los niños se fijaron en el trocito de vela y observaron cómo se derretía lenta y despiadadamente; vieron la media pulgada de pábilo que al fin quedaba solo; vieron la débil llama alzarse y caer, trepar por la fina columna de humo, rezagarse un instante en la cumbre, y luego reinó la más tenebrosa y completa oscuridad."}, {"type": "p", "text": "Nadie podría decir el tiempo que transcurrió hasta que Becky se dio cuenta de que estaba llorando en brazos de Tom. Lo único que sabían era que después de lo que pareció un tiempo inconmensurable, se despertaron de un soñoliento estupor mortal y sus miserias comenzaron de nuevo."}, {"type": "p", "text": "Tom dijo que tal vez fuese domingo, tal vez lunes. Trató de hacer hablar a Becky, pero la pesadumbre de la muchacha era demasiado intensa, pues ya había perdido toda esperanza. Tom dijo que ya debía de hacer tiempo que les echaron en falta y que sin duda habían comenzado a buscarlos. Gritaría y tal vez vendría alguien. Lo probó, pero los ecos distantes resonaron tan pavorosamente en la oscuridad que ya no volvió a intentarlo."}, {"type": "p", "text": "Transcurrieron las horas, y el hambre volvió a atormentar a los cautivos. Quedaba una parte de la mitad del pastel de Tom; la dividieron y se la comieron, pero les pareció que aún tenían más hambre que antes. Aquel pobre bocado solo les despertó el apetito."}]$lira$::jsonb,
  757
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  85,
  'Hallados y perdidos de nuevo (4/4)',
  $lira$[{"type": "p", "text": "—¿Has oído? —dijo Tom de repente."}, {"type": "p", "text": "Los niños contuvieron el aliento y escucharon. Era como un grito muy leve y distante. Tom respondió enseguida y, agarrando a Becky de la mano, descendieron a tientas por el corredor en aquella dirección. Volvió a aguzar el oído; de nuevo se oyó el grito, al parecer más cerca."}, {"type": "p", "text": "—¡Son ellos! —dijo Tom—; ¡ya vienen! Venga, Becky, ahora vamos por buen camino."}, {"type": "p", "text": "La alegría de los prisioneros era casi abrumadora. No obstante, andaban despacio, porque abundaban los pozos y tenían que ir con cuidado. Al cabo de poco encontraron uno y tuvieron que detenerse. Podía tener tres pies de profundidad, como podía tener cien; como quiera que fuese, era imposible seguir adelante. Tom se tendió de bruces y alargó los brazos tanto como pudo. No tocó fondo. Tenían que quedarse allí y esperar que vinieran a buscarlos. Escucharon; era evidente que los gritos se oían cada vez más lejos; un instante después habían desaparecido por completo. ¡Qué abrumadora desesperación! Tom gritó hasta quedarse ronco, pero fue inútil. Habló animadamente a Becky; pero transcurrió un siglo de anhelante espera y aquellos sonidos no volvieron a oírse."}, {"type": "p", "text": "Tom y Becky regresaron a tientas hacia la fuente. El tiempo avanzaba despacio; durmieron otra vez y se despertaron hambrientos y abatidos. Tom creía que ya debía de ser martes."}, {"type": "p", "text": "Entonces se le ocurrió una idea. No lejos de la fuente había algunos pasadizos laterales. Sería mejor explorarlos que soportar el peso de las horas ociosas. Se sacó del bolsillo un hilo bramante de cometa, lo ató a un saliente, y él y Becky empezaron a caminar, Tom a la cabeza, desovillando el hilo bramante mientras avanzaban a tientas."}, {"type": "p", "text": "Veinte pasos más allá el corredor terminaba en un «precipicio». Tom se arrodilló y palpó la parte baja y luego la esquina, tan lejos como pudo alcanzar con las manos; hizo un esfuerzo para estirarse un poco más hacia la derecha, y en aquel momento, a veinte yardas, apareció por detrás de una roca una mano humana que sostenía una vela. Tom prorrumpió en un grito de triunfo y a continuación siguió a la mano el cuerpo al que pertenecía: ¡el del indio Joe!"}, {"type": "p", "text": "Tom se quedó paralizado; no podía moverse. Un instante después sentía un inmenso alivio al ver que el «mexicano» giraba sobre sus talones y desaparecía. Tom se extrañó que Joe no hubiera reconocido su voz y se le hubiese acercado para matarle por su declaración en el tribunal. Los ecos debían de habérsela transformado. No cabía duda de que había sido así, pensó. El terror de Tom le debilitó todos los músculos del cuerpo. Se dijo que si tenía suficientes fuerzas para volver a la fuente se quedaría allí, y no correría el riesgo de volver a encontrarse al indio Joe. Ocultó a Becky lo sucedido. Le dijo que solo había gritado para «tentar a la suerte»."}, {"type": "p", "text": "No obstante, a la larga el hambre y el infortunio se impusieron al temor. Otra tediosa espera en la fuente y otro largo sueño produjeron cambios. Los dos niños se despertaron atormentados por un hambre atroz. Tom creía que ya debía de ser miércoles o jueves, o incluso viernes o sábado, y que habían abandonado la búsqueda. Propuso explorar otro pasadizo. Se sentía capaz de enfrentarse con el indio Joe y con los demás terrores. Pero Becky estaba muy débil. Se había sumido en una melancólica apatía de la que no quería salir. Dijo que se quedaría donde estaba para morir, cosa que no tardaría en suceder. Le dijo a Tom que, si quería, continuase explorando con el hilo bramante de la cometa, pero le suplicó que volviera de vez en cuando con ella y le hablara; y le hizo prometer que cuando llegase el instante supremo se quedaría a su lado y le sostendría la mano entre las suyas hasta que todo hubiese terminado. Tom la besó con una sensación opresiva en la garganta, y fingió que esperaba encontrar a los buscadores o alguna salida de la cueva; entonces cogió el ovillo y el cordel y, avanzando a gatas, se adentró en uno de los pasadizos, atormentado por el hambre y angustiado por los presagios de un fin inminente."}]$lira$::jsonb,
  701
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  86,
  'Hallados (1/2)',
  $lira$[{"type": "p", "text": "Llegó la tarde del martes y se desvaneció en el crepúsculo. El pueblecillo de San Petersburgo aún lloraba. No habían encontrado a los niños perdidos. Habían ofrecido plegarias públicas para ellos, amén de muchísimas plegarias particulares en las que iba el corazón entero del suplicante, pero no llegaba ninguna noticia de la cueva. La mayoría de los buscadores habían abandonado sus pesquisas y habían vuelto a sus ocupaciones habituales, diciendo que era evidente que jamás encontrarían a los niños. La señora Thatcher estaba enferma y la mayor parte del tiempo deliraba. La gente decía que partía el corazón oírla llamar a su hijita y verla alzar la cabeza y escuchar un minuto para después dejarla caer de nuevo con un gemido. La tía Polly estaba sumida en una melancolía persistente, y sus cabellos grises se habían vuelto casi blancos. El martes por la noche el pueblo se entregó al reposo triste y abatido."}, {"type": "p", "text": "En plena noche las campanas del pueblo prorrumpieron en un repique furioso, y un momento después las calles rebosaban de gente frenética y a medio vestir que gritaba: «¡Salid todos! ¡Salid todos! ¡Los han encontrado! ¡Los han encontrado!»."}, {"type": "p", "text": "A la algarabía se unieron trompetas y cacerolas, y el pueblo se juntó en masa y se encaminó al río, encontró a los niños que venían en un coche abierto del que tiraban vociferantes ciudadanos, formó tropel en torno al carruaje, los escoltó hasta su hogar y se precipitó magníficamente por la calle principal voceando un viva tras otro."}, {"type": "p", "text": "Todas las luces estaban encendidas; nadie volvió a acostarse; era la noche más extraordinaria que había conocido la pequeña población. Durante la primera media hora una procesión de habitantes desfilaron por la casa del juez Thatcher, levantaron en brazos a los salvados, los besaron y estrujaron la mano de la señora Thatcher, que intentaba hablar pero no podía, y acababa estallando en sollozos. La felicidad de la tía Polly era absoluta, y la de la señora Thatcher casi casi. No obstante, sería total en cuanto el mensajero enviado a la cueva con la gran noticia se la hubiese comunicado a su esposo. Tom descansaba en un sofá con un anhelante auditorio a su alrededor, y contaba la historia de la maravillosa aventura, introduciendo algunos retoques adicionales que la embellecían. Concluyó con una descripción de cómo dejó a Becky en una de sus exploraciones; cómo recorrió dos pasadizos hasta donde le alcanzó el hilo bramante de la cometa; luego siguió por un tercero hasta desovillar todo el cordel, y se disponía a volver cuando vislumbró una lejana claridad que le pareció luz diurna; abandonó el hilo bramante y fue tanteando hacia ella, introdujo la cabeza y los hombros por un pequeño agujero y vio el amplio Mississippi deslizarse a sus pies. Si hubiera sido de noche, no habría visto la claridad ni habría vuelto a explorar aquel pasadizo. Volvió al lado de Becky y la informó de la buena nueva, pero ella le dijo que no la fastidiara con tonterías, pues estaba cansada, sabía que iba a morirse e incluso lo deseaba. Describió cómo se esforzó y logró convencerla; y cómo Becky murió casi de dicha al llegar al sitio en que se veía la mancha azul de luz diurna. Tom se escurrió por el agujero y luego ayudó a salir a Becky; se sentaron allí y lloraron de alegría. Luego pasaron unos hombres en un bote y Tom los llamó y les explicó su situación y su famélico estado. Al principio los hombres no creyeron su sorprendente historia, «porque —dijeron— estáis cinco millas más abajo del valle en que está la cueva»; luego se los llevaron, remaron hasta una casa, les dieron comida, los hicieron dormir hasta dos o tres horas después de oscurecer, y entonces los llevaron al pueblo. Antes del amanecer encontraron al juez Thatcher y el puñado de hombres que estaban con él en la cueva, por medio de los carretes de hilo que habían dejado a su paso, y los informaron de la gran noticia. Tom y Becky descubrieron pronto que uno no se recuperaba enseguida de tres días y tres noches de hambre y calamidades en la cueva. Guardaron cama todo el miércoles y el jueves, sintiéndose cada vez más cansados y exhaustos. Tom comenzó a salir el jueves, el viernes llegó hasta el pueblo y el sábado estaba casi restablecido, pero Becky no salió de su cuarto hasta el domingo, y con el aspecto de haber pasado una agotadora enfermedad."}]$lira$::jsonb,
  746
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  87,
  'Hallados (2/2)',
  $lira$[{"type": "p", "text": "Tom se enteró de que Huck estaba enfermo y fue a visitarlo el viernes, pero no lo dejaron entrar en su dormitorio; el sábado y el domingo tampoco. Después ya fue admitido a diario, pero le advirtieron que no contara nada de sus aventuras ni introdujese en la conversación ningún tema excitante. La viuda Douglas se quedó en el cuarto para ver si obedecía. Tom se enteró en su casa de lo ocurrido en la colina de Cardiff, y de que habían encontrado el cuerpo del «hombre andrajoso» en el río, junto al embarcadero del vapor; tal vez al intentar escapar se había ahogado."}, {"type": "p", "text": "Unas dos semanas después del salvamento de Tom en la cueva, este fue a visitar a Huck, que ya estaba lo bastante fuerte para mantener una charla excitante, pensando que lo que iba a contarle le interesaría. Como tenía que pasar por delante de la casa del juez Thatcher, Tom se detuvo para ver a Becky. El juez y algunos amigos hicieron hablar a Tom, y alguien le preguntó irónicamente si le gustaría volver otra vez a la cueva. Tom dijo que no tendría inconveniente."}, {"type": "p", "text": "—Otros piensan igual que tú, Tom, estoy seguro. Pero ya me he ocupado de eso. En la cueva ya no volverá a perderse nadie."}, {"type": "p", "text": "—¿Por qué?"}, {"type": "p", "text": "—Porque hace dos semanas hice forrar el portón con planchas de hierro, le puse triple cerradura… y yo tengo las llaves."}, {"type": "p", "text": "Tom se quedó blanco como el papel."}, {"type": "p", "text": "—¿Qué te pasa, muchacho? ¡Deprisa, que traigan un vaso de agua!"}, {"type": "p", "text": "Trajeron el agua y rociaron el rostro de Tom."}, {"type": "p", "text": "—Vaya, ya has vuelto en ti. ¿Qué te ha ocurrido, Tom?"}, {"type": "p", "text": "—Señor juez, ¡el indio Joe está en la cueva!"}]$lira$::jsonb,
  283
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  88,
  'La suerte de Job (1/4)',
  $lira$[{"type": "p", "text": "Unos minutos después se había extendido la noticia, y una docena de botes llenos de hombres del pueblo se dirigían a la cueva de McDougal; el vapor, repleto de pasajeros, no tardó en seguirlos. Tom Sawyer iba en el bote que llevaba al juez Thatcher."}, {"type": "p", "text": "Cuando abrieron la puerta de la cueva apareció una penosa escena a la opaca luz del crepúsculo que iluminaba aquel lugar. El indio Joe yacía muerto en el suelo, con el rostro pegado a la rendija del portón, como si sus ojos anhelantes se hubieran fijado hasta el último instante en la luz y la libertad del mundo exterior. Tom se conmovió, pues sabía por experiencia lo que habría sufrido aquel infeliz. Se sintió enternecido, pero también experimentó una sensación de alivio y de seguridad que le reveló, con una intensidad que hasta entonces no había apreciado del todo, el vasto pavor que lo perseguía desde el día en que declaró contra aquel sanguinario proscrito."}, {"type": "p", "text": "El cuchillo de caza del indio Joe estaba a su lado con la hoja partida en dos. El indio había cortado y desmenuzado por completo el madero inferior del pontón, una tediosa labor en vano, por otra parte, ya que la roca viva formaba un umbral en el lado exterior, y ante aquel pétreo material el cuchillo no había logrado nada; el único daño lo sufrió el mismo cuchillo. Aunque no hubiese habido ningún obstáculo de piedra, su tarea también habría sido inútil, pues si se destruía todo el madero, era imposible que Joe se deslizara por debajo de la puerta, y él lo sabía. Había hecho astillas el madero, tan solo por hacer algo, para pasar el tiempo abrumador, para emplear sus torturadas facultades. Habitualmente uno podía hallarse media docena de trozos de vela clavados en las grietas de aquel vestíbulo, dejados allí por los turistas; pero ya no había ninguno. El prisionero los había buscado y se los había comido. Había logrado también cazar algunos murciélagos, que se había comido, dejando las garras. El desdichado había muerto de hambre. En un lugar próximo una estalagmita había crecido despacio en el suelo a lo largo de los siglos, construida por el goteo de una estalactita del techo. El cautivo había roto la estalagmita, y sobre el tocón había colocado una piedra, en la que había hecho un leve hueco, para recoger la preciosa gota que caía una vez cada tres minutos con la monótona regularidad de un mecanismo de relojería —una cucharadita de postre cada veinticuatro horas—. Aquella gota ya caía cuando las pirámides eran nuevas, cuando se conquistó Troya, cuando se colocaron los cimientos de Roma, cuando Jesucristo fue crucificado, cuando el Conquistador creó el imperio británico, cuando Colón zarpó y cuando la matanza de Lexington fue «una noticia». Sigue cayendo y caerá todavía cuando todas esas cosas se hayan hundido en el interior de la historia y en el crepúsculo de la tradición y las haya engullido la espesa noche del olvido. ¿Acaso todo tiene un propósito y una misión? ¿Cayó aquella gota pacientemente durante cien mil años para satisfacer la necesidad de un efímero insecto humano? ¿Tiene algún otro objetivo importante que cumplir dentro de diez mil años? Como quiera que sea, han transcurrido muchos años desde que el desventurado mestizo excavó un hueco en la piedra para recoger las inapreciables gotas, pero incluso hoy el turista que visita las maravillas de la cueva McDougal contempla durante largo rato aquella patética piedra y aquel lento gotear del agua. La copa del indio Joe ocupa el primer puesto en la lista de las maravillas de la caverna; ni siquiera el «palacio de Aladino» puede parangonarse con ella."}, {"type": "p", "text": "Enterraron al asesino cerca de la boca de la cueva; la gente acudió allí en barcas y carretas desde los pueblos y desde todas las granjas y los villorrios de siete millas a la redonda; trajeron a sus hijos y toda clase de provisiones, y confesaron que casi se habían divertido tanto en el entierro como si hubiesen asistido a la ahorcadura."}, {"type": "p", "text": "El entierro detuvo el crecimiento ulterior de una cosa: la solicitud de perdón al gobernador para el indio Joe. La petición había sido profusamente firmada; se habían celebrado elocuentes reuniones entre ríos de lágrimas, y se había designado una comisión de mujeres sentimentales para que fuesen a ver y a llorar al gobernador, vestidas de riguroso luto, y le suplicaran que fuese un poco clemente y pisotease su deber. Se calculaba que el indio Joe había matado a cinco habitantes del pueblo, pero ¿qué importaba eso? Aunque hubiese sido el mismo Satanás, habría habido un grupo de imbéciles dispuestos a garrapatear sus nombres en una súplica de perdón y a verter en ella alguna lágrima procedente de sus transpirables y permanentemente descompuestos depósitos hidráulicos."}, {"type": "p", "text": "La mañana después del entierro Tom llevó a Huck a un lugar apartado para mantener una conversación importante. Huck se había enterado de la aventura de Tom por el galés y la viuda Douglas, pero Tom dijo que había algo que no le habían contado, y que de eso quería hablarle precisamente. El rostro de Huck se ensombreció."}]$lira$::jsonb,
  854
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  89,
  'La suerte de Job (2/4)',
  $lira$[{"type": "p", "text": "—Sé ya qué es —dijo—. Fuiste al número dos y no encontraste más que whisky. Nadie me dijo que hubieras sido tú; pero en cuanto me enteré del asunto del whisky, adiviné que no podía ser otro; y adiviné también que no habías encontrado el dinero, porque si lo hubieras encontrado, de un modo u otro habrías llegado hasta mí y me lo habrías dicho, aunque a los demás no les dijeras palabra. Tom, siempre creí que nunca conseguiríamos apoderarnos de ese dinero."}, {"type": "p", "text": "—Debes saber, Huck, que yo nunca delaté al tabernero. Ya sabes que en la taberna no pasó nada el sábado que fui al picnic. ¿No recuerdas que aquella noche estábamos de guardia?"}, {"type": "p", "text": "—Es cierto. Parece que haya pasado un año. Fue la misma noche que seguí al indio Joe a casa de la viuda."}, {"type": "p", "text": "—¿Que lo seguiste?"}, {"type": "p", "text": "—Sí, pero no me descubras. Supongo que el indio Joe habrá dejado amigos, y no quiero que me amarguen la vida y me jueguen una mala pasada. Si no hubiera sido por mí, ahora estaría muy tranquilo en Texas."}, {"type": "p", "text": "Entonces Huck relató confidencialmente toda su aventura a Tom, que solo estaba enterado de la parte del galés."}, {"type": "p", "text": "—Bueno —dijo a poco Huck volviendo a la cuestión principal—, sin duda el que pescó el whisky en el número dos pescó también el dinero. De todas formas, está perdido para nosotros, Tom."}, {"type": "p", "text": "—Huck, ¡ese dinero no ha estado nunca en el número dos!"}, {"type": "p", "text": "—¿Qué? —Huck escrutó el rostro de su camarada—. Tom, ¿vuelves a estar sobre la pista de ese dinero?"}, {"type": "p", "text": "—Está en la cueva, Huck."}, {"type": "p", "text": "Los ojos de Huck chispearon."}, {"type": "p", "text": "—Repítelo, Tom."}, {"type": "p", "text": "—El dinero está en la cueva."}, {"type": "p", "text": "—Tom, te lo suplico, ¿hablas en serio o en broma?"}, {"type": "p", "text": "—En serio, Huck; tan en serio como no he dicho otra cosa en toda mi vida. ¿Quieres venir conmigo y ayudarme a sacarlo?"}, {"type": "p", "text": "—¡Claro que sí! Iré si está en algún lugar al que podamos llegar sin perdernos."}, {"type": "p", "text": "—Huck, podemos llegar allí sin dificultad."}, {"type": "p", "text": "—¡Estupendo! ¿Cómo es que supones que el dinero está…?"}, {"type": "p", "text": "—No quieras saber nada hasta que lleguemos allí. Si no lo encontramos, estoy dispuesto a regalarte mi tambor y todo lo que tengo en el mundo. Palabra, te lo doy."}, {"type": "p", "text": "—Muy bien, eso es hablar. ¿Cuándo iremos?"}, {"type": "p", "text": "—Enseguida, si quieres. ¿Te sientes lo bastante fuerte?"}, {"type": "p", "text": "—¿Está muy adentro de la cueva? Hace ya tres o cuatro días que salgo, pero no creo tener fuerzas para andar más de una milla, Tom."}, {"type": "p", "text": "—Está por el camino que seguiría todo el mundo, Huck, a unas cinco millas al interior, pero hay un atajo muy corto que solo conozco yo. Huck, te llevaré directamente allí en un bote. Lo dejaré en la corriente a la ida y remaré a la vuelta. No tendrás que mover un dedo."}, {"type": "p", "text": "—Pues no perdamos tiempo, Tom."}, {"type": "p", "text": "—Mira, necesitamos un poco de pan y carne, y nuestras pipas, y un saquito o dos, y dos o tres bramantes de cometa, y unas cuantas cosas de esas que han salido ahora y que llaman fósforos. Te aseguro que más de una vez deseé haber tenido algunos cuando estuve allí dentro."}, {"type": "p", "text": "A primera hora de la tarde los muchachos tomaron un pequeño bote prestado a un ciudadano que estaba ausente, y partieron sin dilación. Cuando se hallaban varias millas más abajo de la cueva Tom dijo:"}, {"type": "p", "text": "—Mira ese peñascal que viene ofreciendo el mismo aspecto desde la boca de la cueva, sin casas ni bosque, todo son matorrales. ¿No ves aquel lugar blancuzco, ahí abajo, donde ha habido un desprendimiento de tierra? Pues bien, es una de mis marcas. Ahora vamos a tierra."}, {"type": "p", "text": "Desembarcaron."}, {"type": "p", "text": "—Desde aquí, Huck, podrías tocar el agujero por donde salí con una caña de pescar. Veamos si lo encuentras."}, {"type": "p", "text": "Huck buscó a su alrededor y no halló nada. Tom se dirigió majestuosamente a un espeso matorral."}, {"type": "p", "text": "—¡Aquí está! —dijo—. Míralo, Huck; es el agujero más formidable del país. Ni una palabra de dónde está. Hace mucho tiempo que quería convertirme en ladrón, pero sabía que me hacía falta un escondrijo así y no había manera de encontrarlo. Ahora ya lo tenemos; no se lo diremos a nadie y solo lo sabrán Joe Harper y Ben Rogers, porque, naturalmente, hay que formar una banda; si no, ya no valdría la pena. La Banda de Tom Sawyer. Suena genial, ¿no te parece, Huck?"}, {"type": "p", "text": "—Ya lo creo, Tom. ¿Y a quién robaremos?"}, {"type": "p", "text": "—Casi a todo el mundo. A los viandantes; es la costumbre general."}, {"type": "p", "text": "—¿Y los mataremos?"}, {"type": "p", "text": "—No, no siempre. Los tendremos prisioneros en la cueva hasta que paguen un rescate."}, {"type": "p", "text": "—¿Qué es un rescate?"}, {"type": "p", "text": "—Dinero. Se les hace recoger una buena suma entre sus amigos; y retienes a los prisioneros un año, y si aún no han pagado los matas. Es la costumbre. Solo que a las mujeres no las matas. Las encierras, pero sin hacerles ningún daño. Siempre son guapas y ricas y están muy asustadas. Te quedas sus relojes y sus joyas, pero siempre te quitas el sombrero y les hablas cortésmente. No hay gente más educada que los ladrones; eso puedes verlo en cualquier libro. Las mujeres se enamoran de ti, y cuando ya llevan en la cueva una o dos semanas dejan de llorar, y entonces ya no puedes conseguir que se vayan. Si las echas, dan media vuelta y regresan. En todos los libros es así."}]$lira$::jsonb,
  893
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  90,
  'La suerte de Job (3/4)',
  $lira$[{"type": "p", "text": "—Es divertidísimo, Tom. Creo que es mejor que piratear, porque así estás cerca de casa y de los circos que llegan."}, {"type": "p", "text": "Mientras hablaban, los muchachos habían preparado las cosas, y entraron por el agujero, Tom a la cabeza. Avanzaron hasta el extremo más apartado del túnel, entonces ataron los bramantes de cometa empalmados y prosiguieron el camino. Unos cuantos pasos más allá se encontraron ante la fuente, y Tom sintió que un estremecimiento le recorría el cuerpo. Mostró a Huck el fragmento de pabilo pegado a una masa de arcilla, contra la pared, y le contó cómo él y Becky habían visto la llama debatirse y expirar. Luego Huck y Tom comenzaron a bajar la voz hasta hablar en un susurro, pues la quietud y las tinieblas del lugar les oprimían el corazón. Siguieron avanzando, y pronto enfilaron otro corredor hasta llegar al «precipicio». Las velas revelaron que en realidad no era ningún despeñadero, sino una abrupta colina de arcilla de unos veinte o treinta pies de altura."}, {"type": "p", "text": "—Voy a enseñarte una cosa, Huck —murmuró Tom. Levantó la vela y dijo—: Mira al rincón hasta donde te alcance la vista. ¿Lo ves? Allí, en aquella enorme roca, hecho con humo de vela."}, {"type": "p", "text": "—Tom, ¡es una cruz!"}, {"type": "p", "text": "—Pues, bien, ¿dónde está el número dos? «Debajo de la cruz», ¿no? Allí vi al indio Joe con la vela. Tras observar un rato la mística señal, Huck dijo con la voz temblorosa:"}, {"type": "p", "text": "—Tom, ¡vámonos de aquí!"}, {"type": "p", "text": "—¿Qué dices? ¿Vamos a dejar el tesoro?"}, {"type": "p", "text": "—Estoy seguro de que el espíritu del indio Joe anda rondando por aquí."}, {"type": "p", "text": "—No es posible, Huck, no es posible. Rondará por el sitio donde murió, en la boca de la cueva, a cinco millas de aquí."}, {"type": "p", "text": "—No, Tom, por allí no. Rondará por donde esté el dinero. Sé cómo se las gastan los fantasmas, y tú también."}, {"type": "p", "text": "Tom empezó a temer que Huck tuviese razón. Se acumularon los recelos en su pensamiento. De pronto se le ocurrió una idea."}, {"type": "p", "text": "—¡Qué tontos somos, Huck! El espíritu del indio Joe no puede rondar por un sitio donde hay una cruz. La observación fue acertada y produjo su efecto."}, {"type": "p", "text": "—No había pensado en ello, Tom. Pero es así. Esa cruz es nuestra salvación. Bueno, ahora bajaremos a buscar la caja."}, {"type": "p", "text": "Tom empezó a cortar toscos peldaños en la arcilla mientras descendían. Huck le seguía. Cuatro pasadizos salían de la pequeña caverna en la que estaba la enorme roca. Los muchachos examinaron tres sin resultado. En el más cercano a la base de la roca encontraron una pequeña cavidad donde había un jergón de mantas; hallaron también un tirante viejo, un trozo de pellejo de tocino y los huesos bien roídos de dos o tres aves. Pero allí no había caja alguna. Los muchachos buscaron y rebuscaron en vano. Tom dijo:"}, {"type": "p", "text": "—Joe dijo «debajo de la cruz». Pues, bien, este es el sitio más cercano que hay debajo de la cruz. No puede estar debajo de la misma roca, porque está clavada al suelo."}, {"type": "p", "text": "Volvieron a buscar por todas partes, y entonces se sentaron desalentados. Huck no sabía qué sugerir. Poco después dijo Tom:"}, {"type": "p", "text": "—Mira, Huck, hay huellas de pisadas y algunas gotas de sebo sobre la arcilla en ese lado de la roca, pero no en los otros. ¿Cómo te lo explicas? Apuesto a que el dinero está debajo de la roca. Voy a cavar en la arcilla."}, {"type": "p", "text": "—No es mala idea, Tom —dijo Huck animado."}, {"type": "p", "text": "No tardó en entrar en acción el «auténtico Barlow» de Tom, y aún no había cavado cuatro pulgadas cuando tocó madera."}, {"type": "p", "text": "—Huck, ¿lo oyes?"}, {"type": "p", "text": "Huck se puso a cavar con Tom. Pronto fueron descubiertas algunas tablas que ocultaban una grieta natural que se adentraba por debajo de la roca. Después de quitar las tablas, Tom se introdujo por la grieta y sostuvo la vela todo lo lejos que pudo bajo la roca, pero dijo que no podía ver el final de la hendidura. Propuso explorarla. Se agachó y avanzó; el estrecho camino descendía gradualmente. Siguió su tortuoso curso, primero a la derecha y luego a la izquierda, con Huck a sus talones. Poco después Tom dobló un breve recodo y exclamó:"}, {"type": "p", "text": "—¡Cielos! Huck, aquí está."}, {"type": "p", "text": "Allí estaba la caja del tesoro, ocupando una pequeña caverna junto con un diminuto barril de pólvora vacío, un par de fusiles en fundas de cuero, dos o tres pares de viejos mocasines, un cinturón de cuero y otros escombros bien empapados por el goteo del agua."}, {"type": "p", "text": "—Por fin es nuestro —dijo Huck hundiendo la mano entre las empañadas monedas—. ¡Somos ricos, Tom!"}, {"type": "p", "text": "—Siempre creí que lo conseguiríamos. Huck. Parece mentira, pero ya lo tenemos. Oye, no perdamos tiempo aquí dentro. Déjame ver si puedo levantar la caja."}, {"type": "p", "text": "Pesaba unos dos kilos y medio. Tom podía levantarla con más o menos contorsiones, pero le resultaba imposible llevarla como era debido."}, {"type": "p", "text": "—Ya me lo figuraba yo —dijo—. Cuando se la llevaron aquel día de la casa hechizada, vi cómo pesaba. He hecho bien al acordarme de traer los saquitos."}]$lira$::jsonb,
  837
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  91,
  'La suerte de Job (4/4)',
  $lira$[{"type": "p", "text": "Una vez que hubieron guardado el dinero en los sacos, los muchachos lo subieron a la roca de la cruz."}, {"type": "p", "text": "—Vamos a por los fusiles y lo demás —dijo Huck."}, {"type": "p", "text": "—No, Huck, los dejaremos ahí. Son precisamente los avíos que necesitamos para ser ladrones. Los guardaremos siempre ahí y allí celebraremos también nuestras orgías. Es un lugar ideal para celebrar orgías."}, {"type": "p", "text": "—¿Qué son orgías?"}, {"type": "p", "text": "—No lo sé. Pero como los ladrones siempre celebran orgías, nosotros también tenemos que celebrarlas. Vamos, Huck llevamos aquí mucho tiempo. Me parece que ya es tarde y tengo un hambre canina. Comeremos y fumaremos cuando lleguemos al bote."}, {"type": "p", "text": "No tardaron en aparecer entre los arracimados matorrales, echaron una prudente ojeada en derredor, vieron la costa libre, y enseguida se hallaban en el bote comiendo y fumando. Cuando el sol comenzó a hundirse en el horizonte, movieron los remos y emprendieron el camino de vuelta. Tom costeó la ribera mientras oscurecía, charlando animadamente con Huck, y desembarcaron poco después."}, {"type": "p", "text": "—Lo que haremos ahora —dijo Tom— es esconder el dinero en el desván del cobertizo de la viuda; mañana nos reuniremos, lo contaremos y haremos las partes, y entonces habrá que buscar un sitio en el bosque donde pueda estar seguro. Quédate aquí vigilando los sacos mientras yo me cojo un momento la carretilla de Benny Taylor; no tardaré un minuto."}, {"type": "p", "text": "Desapareció y volvió al poco rato con la carretilla, colocó en ella los dos sacos, los cubrió con algunos viejos andrajos, y se puso en camino tirando de la carga. Al llegar a la casa del galés, los muchachos se detuvieron para descansar. En el preciso instante en que se disponían a proseguir salió el galés y dijo:"}, {"type": "p", "text": "—¡Eh! ¿Quién está ahí?"}, {"type": "p", "text": "—Huck y Tom Sawyer."}, {"type": "p", "text": "—¡Magnífico! Venid conmigo, muchachos; os están esperando todos. Vamos, deprisa; ya tiraré yo de la carretilla. Caramba, no es tan ligera como creía. ¿Lleváis ladrillos? ¿O hierro viejo?"}, {"type": "p", "text": "—Hierro viejo —dijo Tom."}, {"type": "p", "text": "—Me lo figuraba; los chicos de este pueblo emplean más tiempo y más trabajo en conseguir sesenta centavos de hierro viejo para vender a la fundición del que emplearían para ganar el doble en una tarea normal. Pero así es la naturaleza humana."}, {"type": "p", "text": "Los muchachos quisieron saber el motivo de la premura."}, {"type": "p", "text": "—No os preocupéis; ya lo veréis cuando lleguemos a casa de la viuda Douglas."}, {"type": "p", "text": "Huck llevaba muchos años acostumbrado a que le acusaran de falso y dijo con inquietud:"}, {"type": "p", "text": "—Señor Jones, nosotros no hemos hecho nada malo."}, {"type": "p", "text": "El galés se echó a reír."}, {"type": "p", "text": "—Bueno, no lo sé, Huck, no lo sé. Pero ¿no sois buenos amigos tú y la viuda?"}, {"type": "p", "text": "—Sí. Por lo menos, ella ha sido muy buena conmigo."}, {"type": "p", "text": "—Entonces ¿por qué has de tener miedo?"}, {"type": "p", "text": "La pregunta no quedó contestada del todo en el lento cerebro de Huck hasta que fue empujado, junto con Tom, hacia el salón de la señora Douglas. El señor Jones dejó la carretilla cerca de la puerta y los siguió."}, {"type": "p", "text": "La estancia estaba espléndidamente iluminada, y toda la gente que representaba algo en el pueblo se encontraba allí. Estaban los Thatcher, los Harper, los Roger, la tía Polly, Sid, Mary, el ministro, el director del periódico local y muchísimos más, todos ataviados con sus mejores galas. La viuda recibió a los muchachos todo lo cordialmente que es posible recibir a dos seres con aquella facha. Iban cubiertos de arcilla y de manchas de sebo. La tía Polly se ruborizó humillada, frunció el ceño y movió la cabeza amenazadora. Sin embargo, nadie sufrió ni la mitad que los chicos."}, {"type": "p", "text": "—Tom aún no había vuelto a casa —dijo el señor Jones—, así que he renunciado a él; pero me he tropezado con Huck y con él delante de mi puerta, y los he traído aquí a toda prisa."}, {"type": "p", "text": "—Y ha hecho usted muy bien —dijo la viuda—. Venid conmigo, niños. —Se los llevó a un dormitorio y dijo—: Ahora lavaos y vestíos. Aquí hay dos trajes nuevos, camisas, calcetines y todo lo necesario. Son de Huck; no, no me des las gracias, Huck; el señor Jones compró uno y yo el otro. Pero os irán bien a los dos. Vestíos. Os esperamos; bajad en cuanto os hayáis arreglado."}, {"type": "p", "text": "Y luego la viuda Douglas se marchó."}]$lira$::jsonb,
  704
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  92,
  'Ríos de oro',
  $lira$[{"type": "p", "text": "—Tom, si encontráramos una cuerda —dijo Huck—, podríamos escapar. La ventana no es muy alta."}, {"type": "p", "text": "—¡Qué tontería! ¿Para qué quieres escapar?"}, {"type": "p", "text": "—No estoy acostumbrado a tanta gente. No puedo resistirlo. Yo no bajo, Tom."}, {"type": "p", "text": "—¡No seas estúpido! No es nada. A mí no me importa en absoluto. Ya cuidaré de ti."}, {"type": "p", "text": "Entonces apareció Sid."}, {"type": "p", "text": "—Tom —dijo—, la tía Polly te ha esperado toda la tarde. Mary te había preparado la ropa del domingo y todos estaban inquietos por ti. Oye, ¿no es sebo y arcilla lo que hay en tu ropa?"}, {"type": "p", "text": "—Mira, Sid, será mejor que te ocupes de tus asuntos. Y dime, ¿a qué viene tanta fiesta?"}, {"type": "p", "text": "—Es una de las reuniones que suele ofrecer la viuda. Esta vez la dedica al galés y a sus hijos por haberla salvado la otra noche. Y, escúchame, puedo decirte algo si te interesa."}, {"type": "p", "text": "—¿Qué?"}, {"type": "p", "text": "—El viejo Jones quiere dar una sorpresa a la gente reunida esta noche, pero yo he oído que se lo contaba a la tía como un secreto, y supongo que ahora es ya un secreto a voces. Todo el mundo lo sabe; la viuda también, aunque hace ver que no. El señor Jones necesitaba que Huck estuviese presente, pues sin Huck no podría contar su gran secreto, ¿sabes?"}, {"type": "p", "text": "—¿De qué secreto hablas, Sid?"}, {"type": "p", "text": "—Que Huck siguió a los rateros hasta el portillo. Supongo que el viejo Jones piensa causar gran sensación con su sorpresa, pero te apuesto a que se le volverá agua de borrajas."}, {"type": "p", "text": "Sid dejó escapar una risita llena de contento y satisfacción."}, {"type": "p", "text": "—Sid, ¿se lo dijiste tú?"}, {"type": "p", "text": "—¿Qué más da? Alguien lo dijo, y ya está."}, {"type": "p", "text": "—Sid, en este pueblo solo hay una persona bastante mezquina para hacerlo, y esa persona eres tú. Si hubieses estado en el sitio de Huck, te habrías escabullido colina abajo y no habrías avisado a nadie. Tú no puedes hacer más que cosas mezquinas, y no puedes soportar que alaben a otro porque hizo una buena acción. Toma; no, no me des las gracias, como dice la viuda… —Y Tom le dio un par de sopapos a Sid y lo acompañó hasta la puerta con algunos puntapiés—. Y ahora cuéntaselo a la tía Polly si te atreves, y mañana verás."}, {"type": "p", "text": "Poco después los invitados de la viuda estaban sentados para la cena, y una docena de chiquillos rodeaban unas mesitas adyacentes, en el mismo comedor, según la moda de aquel país y de aquellos tiempos. En el momento oportuno el señor Jones pronunció su discursito, en el que agradeció a la viuda el honor que le hacía a él y a sus hijos, pero dijo que había otra persona, cuya modestia… Soltó el secreto de la participación de Huck en la aventura con el estilo más dramático y florido de que pudo hacer gala, pero la sorpresa que ocasionó fue en gran parte fingida y no tan efusiva y clamorosa como podía haber sido en circunstancias más felices. Con todo, la viuda dio muestras de asombro bastante aceptables y dedicó tantos cumplidos y tanta gratitud a Huck que este olvidó la casi intolerable incomodidad de su traje nuevo ante la absolutamente intolerable incomodidad de convertirse en el blanco de todas las miradas y de todas las alabanzas."}, {"type": "p", "text": "La viuda Douglas dijo que pensaba ofrecer un hogar a Huck bajo su techo y que le daría una educación; y que cuando tuviese dinero ahorrado le haría entrar en los negocios de una manera modesta. Tom no iba a perder aquella oportunidad."}, {"type": "p", "text": "—Huck no lo necesita. ¡Huck es rico! —dijo."}, {"type": "p", "text": "Solo un sobrehumano esfuerzo de los buenos modales de los asistentes contuvo la consiguiente y adecuada carcajada de cumplido que merecía tan divertida chanza. Pero el silencio que siguió era un tanto grosero y Tom lo rompió:"}, {"type": "p", "text": "—Huck tiene dinero. Tal vez no lo crean ustedes, pero tiene muchísimo dinero. No sonrían, no; me parece que puedo demostrarlo. Esperen un minuto."}, {"type": "p", "text": "Tom salió precipitadamente de la estancia. Los comensales se miraron unos a otros, interesados y perplejos. Luego miraron a Huck, que permanecía mudo."}, {"type": "p", "text": "—Sid, ¿qué le ocurre a Tom? —preguntó la tía Polly—. No hay manera de saber lo que ese muchacho…"}, {"type": "p", "text": "Tom apareció encorvado por el peso de los sacos, y la tía Polly no terminó la frase. Tom vertió la masa de piezas amarillas sobre la mesa y dijo:"}, {"type": "p", "text": "—¿Qué dicen ahora? La mitad es de Huck y la otra mitad mía."}, {"type": "p", "text": "Aquel espectáculo dejó a los presentes sin habla. Todos miraban aquellas riquezas mudos de asombro. Luego hubo una petición unánime de explicaciones. Tom dijo que podía ofrecerlas, y así lo hizo. El relato fue extenso, pero rebosante de interés. Apenas tuvo lugar una interrupción que rompiese el hechizo de su fluidez. Cuando hubo terminado, el señor Jones dijo:"}, {"type": "p", "text": "—Creía haber preparado una pequeña sorpresa para la fiesta, pero ahora ya no vale nada. Esta otra la empequeñece mucho, lo reconozco."}, {"type": "p", "text": "Contaron el dinero. La suma ascendía a poco más de doce mil dólares. Era más de lo que cualquiera de los presentes había visto junto en su vida, pese a que algunos de ellos fuesen considerablemente más ricos en propiedades."}]$lira$::jsonb,
  855
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  93,
  'El respetable Huck se une a la banda (1/3)',
  $lira$[{"type": "p", "text": "El lector puede estar seguro de que la inesperada fortuna de Tom y Huck conmocionó al mísero pueblecillo de San Petersburgo. Una suma tan vasta, toda en dinero contante y sonante, parecía bordear lo increíble. Se habló del hecho y fue envidiado y glorificado hasta que la razón de muchos de los ciudadanos vaciló bajo el esfuerzo de tan dañina exaltación. Todas las casas hechizadas de San Petersburgo y de los pueblos limítrofes fueron desmontadas tabla por tabla y se cavaron y escudriñaron sus cimientos en busca de tesoros ocultos; y no lo hicieron chicuelos, sino hombres, algunos de los cuales eran, además, hombres graves y nada románticos. Dondequiera que apareciesen Tom y Huck eran festejados, admirados y observados. Los muchachos no podían recordar que sus observaciones hubiesen sido alguna vez de peso; pero de pronto sus palabras eran escuchadas y repetidas; todo cuanto hacían se consideraba algo notable; era evidente que habían perdido el poder de hacer o decir cosas vulgares; se rebuscó, además, en su historia y se descubrió que poseía rasgos de ilustre originalidad. El diario local publicó sucintas biografías de los dos chicos."}, {"type": "p", "text": "La viuda Douglas invirtió el dinero de Huck al 6 por ciento, y el juez Thatcher, a instancias de la tía Polly, hizo otro tanto con el de Tom. Cada uno de los muchachos percibía una renta prodigiosa: un dólar cada día laborable del año y medio dólar los domingos. Era exactamente lo que ganaba el pastor, es decir, lo que le habían prometido —generalmente no podía cobrarlo—. Con poco más de un dólar por semana bastaba, en aquellos tiempos felices, para mantener, alojar y educar a un muchacho… y hasta para vestirlo y lavarlo."}, {"type": "p", "text": "El juez Thatcher se había formado un alto concepto de Tom. Dijo que un chico cualquiera no habría logrado sacar a su hija de la cueva. Cuando Becky le contó a su padre, de un modo estrictamente confidencial, que en la escuela Tom había recibido la azotaina en su lugar, el juez se emocionó; y cuando ella suplicó gracia por la mentira que había dicho Tom a fin de cargar sobre sus hombros el castigo destinado a su compañera, el juez dijo con gran entusiasmo que era una mentira noble, generosa y magnánima, una mentira que merecía levantar la cabeza y pasar a la historia junto con la tan loada veracidad de George Washington acerca del hacha. Becky se dijo que su padre jamás había mostrado un aspecto tan majestuoso y soberbio como al decir aquello, dando zancadas y golpeando el suelo con el pie. Becky fue enseguida a contárselo a Tom."}, {"type": "p", "text": "El juez Thatcher esperaba ver a Tom convertido algún día en un gran abogado o en un gran soldado. Dijo que haría todo lo posible para que Tom fuese admitido en la Academia Militar Nacional y educado luego en el mejor colegio jurídico del país. Así estaría preparado para cualquiera de las dos carreras o para ambas a la vez."}, {"type": "p", "text": "La fortuna de Huck Finn y el hecho de encontrarse bajo la protección de la viuda Douglas lo introdujeron en la buena sociedad, es decir, lo arrastraron a ella y lo metieron dentro de un empellón. Casi sufría más de lo que podía soportar. Los criados de la viuda lo mantenían limpio, cuidado, peinado y cepillado, y lo acostaban cada noche entre sábanas antipáticas sin la más leve mácula o rotura que pudiese apretar contra el corazón y reconocer como amiga. Tenía que comer con cuchillo y tenedor, tenía que usar servilleta, vaso y plato, tenía que aprender de los libros, tenía que ir a la iglesia, tenía que hablar con tanta propiedad que el lenguaje se le hacía insípido en la boca; dondequiera que se dirigiese, las barreras y los grilletes de la civilización le cerraban el paso y lo ataban de pies y manos."}, {"type": "p", "text": "Durante tres semanas soportó bravamente sus miserias, y un buen día desapareció. La viuda, muy desesperada, lo buscó por todas partes durante cuarenta y ocho horas. El pueblo estaba muy preocupado; escudriñaron el río en busca de su cuerpo. A primera hora de la mañana del tercer día, Tom Sawyer, con certero instinto, se dedicó a buscar en unos barriles vacíos que había detrás del abandonado matadero, y en uno de ellos encontró al fugitivo. Huck había dormido allí; acababa de desayunar algunas fruslerías que había hurtado y estaba voluptuosamente tumbado, fumando una pipa. Iba sucio, despeinado y vestía los mismos andrajos que habían hecho de él un tipo pintoresco en los días que era libre y feliz. Tom lo sacó de allí, le contó los trastornos que estaba causando y trató de convencerlo para que volviera a casa. El rostro de Huck perdió su plácida expresión y se volvió melancólico."}]$lira$::jsonb,
  791
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  94,
  'El respetable Huck se une a la banda (2/3)',
  $lira$[{"type": "p", "text": "—No me hables de eso, Tom —dijo—. Lo he probado y no funciona; no funciona, Tom; no es para mí; no estoy acostumbrado a ello. La viuda es muy buena y me quiere; pero no puedo aguantarla. Cada mañana me hace levantar a la misma hora; me hace lavar, me peinan que da asco; no permite que me duerma en el cobertizo; tengo que llevar ese maldito traje que me asfixia, Tom; es como si no dejara circular el aire; y todo está tan condenadamente limpio que no puedo sentarme, ni echarme al suelo, ni arrastrarme por donde me plazca; creo que hace varios años que no me he deslizado por la puerta de una bodega; y tengo que ir a la iglesia y sudar y sudar; aborrezco los sermones. Allí no puedo atrapar una mosca, ni mascar tabaco. Tengo que llevar zapatos todos los domingos. La viuda come a toque de campana; se acuesta a toque de campana; se levanta a toque de campana; todo es tan horriblemente metódico que se me hace insoportable."}, {"type": "p", "text": "—Pero ¡si todos vivimos así, Huck!"}, {"type": "p", "text": "—Eso no importa, Tom. Yo no soy como los demás y no puedo resistirlo. Es horrible estar encadenado así. Tengo que pedir permiso para ir a pescar; tengo que pedir permiso para ir a nadar. ¡Que me ahorquen si no he de pedir permiso para todo! Además, tengo que hablar tan fino que me desespera. Últimamente subía al desván un rato cada día a jurar para darle gusto a la lengua, o de lo contrario habría reventado, Tom. La viuda no me dejaba fumar; no me dejaba gritar, ni bostezar, ni desperezarme, ni rascarme delante de la gente —y entonces, con un espasmo de especial irritación y ofensa— y, ¡Dios bendito!, no paraba de rezar. Nunca he visto una mujer igual. He tenido que escabullirme, Tom, no me quedaba otro remedio. Y además, pronto se abrirá la escuela, y tendría que ir a ella; bueno, y eso no lo aguanto, Tom. Mira, Tom, ser rico no es lo que parece a primera vista. No es más que una molestia tras otra, y un sudar continuo, y un desear morirse a cada minuto. Estas son las ropas que me convienen, y este barril también, y no volveré a separarme de ellos. Tom, si no hubiese sido por el dinero, no me habría visto en semejante lío; así, pues, te cedo mi parte; súmala a la tuya y dame diez centavos de vez en cuando, no con mucha frecuencia, porque solo me importa lo que cuesta obtener, y ahora vete y discúlpame con la viuda."}, {"type": "p", "text": "—Huck, sabes que no puedes hacer esto. No estaría bien y, además, si llevaras esa vida una temporada, acabaría gustándote."}, {"type": "p", "text": "—¡Gustándome! Sí, como me gustaría un brasero encendido si me sentara un buen rato encima. No, Tom, no quiero ser rico y no quiero vivir en esas condenadas casas que asfixian. Me gusta el bosque, y el río, y los barriles, y me quedaré con ellos. ¡Maldita sea! Justamente cuando teníamos fusiles y una cueva, y todo dispuesto para ser ladrones, ocurre eso y lo echa todo a perder."}, {"type": "p", "text": "Tom vio el momento oportuno."}, {"type": "p", "text": "—A mí, Huck, ser rico no me impedirá convertirme en ladrón."}, {"type": "p", "text": "—¿No? ¡Córcholis!, ¿estás hablando en serio, Tom?"}, {"type": "p", "text": "—Tan en serio como estoy aquí sentado. Pero te advierto, Huck, que no podremos dejar que entres en la banda si no eres una persona respetable."}, {"type": "p", "text": "La alegría de Huck se extinguió."}, {"type": "p", "text": "—¿No me dejaréis entrar, Tom? Bien me dejasteis ser pirata."}, {"type": "p", "text": "—Sí, pero ahora es distinto. Por lo general un ladrón tiene más categoría que un pirata. En algunos países pertenecen a la alta nobleza. Son duques y cosas por el estilo."}, {"type": "p", "text": "—Oye, Tom, ¿no has sido siempre un buen amigo mío? No vas a dejarme fuera, ¿eh, Tom? Eso no lo harías, dime, ¿verdad que no, Tom?"}, {"type": "p", "text": "—Huck, no quisiera ni quiero, pero ¿qué diría la gente? Pues diría: «¿La Banda de Tom Sawyer? ¡Valientes desastrosos!». Y lo dirían por ti, Huck. A ti no te gustaría, y a mí tampoco. Huck guardó silencio durante un rato, mientras libraba una dura batalla en su interior."}]$lira$::jsonb,
  693
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  95,
  'El respetable Huck se une a la banda (3/3)',
  $lira$[{"type": "p", "text": "—Bien —dijo al fin—, si me dejas formar parte de la banda, Tom, pasaré otro mes con la viuda y veré si llego a soportar esa vida."}, {"type": "p", "text": "—Muy bien, Huck, así se habla. Vamos, compañero, y ya le pediré a la viuda que afloje un poco, Huck."}, {"type": "p", "text": "—¿Lo harás, Tom, se lo dirás? ¡Magnífico! Si ella se muestra benigna en lo peor, fumaré y juraré a hurtadillas, y me saldré con la mía o reventaré. ¿Cuándo empezará a funcionar la banda y seremos ladrones?"}, {"type": "p", "text": "—Muy pronto. Puede que reunamos a los muchachos esta noche para la iniciación."}, {"type": "p", "text": "—¿Para la qué?"}, {"type": "p", "text": "—La iniciación."}, {"type": "p", "text": "—¿Y qué es eso?"}, {"type": "p", "text": "—Jurar que uno ayudará siempre a los compañeros y nunca descubrirá los secretos de la banda aunque lo hagan pedazos, y que matará a cualquiera, y a toda su familia, que perjudique a uno de la banda."}, {"type": "p", "text": "—Estupendo, te digo que es estupendo, Tom."}, {"type": "p", "text": "—Claro que sí. Y esos juramentos se deben hacer a medianoche, en el lugar más solitario y más pavoroso que uno encuentre; una casa hechizada es lo ideal, pero ahora están todas echadas a perder."}, {"type": "p", "text": "—De todos modos, eso de hacerlo a medianoche es estupendo, Tom."}, {"type": "p", "text": "—Sí que lo es. Y se tiene que jurar sobre un ataúd, y firmar con sangre."}, {"type": "p", "text": "—Eso ya vale la pena. Mira, es un millón de veces más divertido que ser pirata. Me quedaré con la viuda hasta que me pudra, Tom; y si llego a convertirme en un bandido de primer orden y todo el mundo habla de mí, me parece que se sentiría orgullosa de haber sido ella quien me ha recogido del arroyo."}, {"type": "h", "text": "Conclusión"}, {"type": "p", "text": "Aquí termina la crónica. Como se trata estrictamente de la historia de un muchacho, tiene que detenerse aquí; no podría seguir adelante sin convertirse en la historia de un hombre. El que escribe una novela de personas mayores ya sabe dónde debe concluir —en el matrimonio—, pero cuando escribe sobre chiquillos, tiene que detenerse donde mejor puede."}, {"type": "p", "text": "Muchos de los personajes que aparecen en el libro viven todavía, y son prósperos y felices. Tal vez algún día sea interesante reanudar la historia de los más jóvenes para ver en qué clase de hombres y mujeres se convirtieron; por tanto, lo más acertado será no revelar nada, por ahora, de esa parte de su existencia."}, {"type": "h", "text": "Fin Mark Twain,"}, {"type": "p", "text": "seudónimo de Samuel Langhorne Clemens, nació en Florida, Missouri, en 1835."}, {"type": "p", "text": "Pasó su infancia y adolescencia en Hannibal, a orillas del río Mississippi. En 1861 viajó a Nevada como ayudante personal de su hermano, que acababa de ser nombrado secretario del gobernador. Más tarde, en San Francisco, trabajó en The Morning Call. En 1866 realizó un viaje de seis meses por las islas Hawái y al año siguiente embarcó hacia Europa. Resultado de este último viaje fue uno de sus primeros éxitos editoriales, Inocentes en el extranjero, publicado en 1869. En 1876 publicó su segunda obra de gran éxito, Las aventuras de Tom Sawyer, y en 1885 la que los críticos consideran su mejor obra, Las aventuras de Huckleberry Finn. Murió en 1910 en Redding, Connecticut."}]$lira$::jsonb,
  516
);


-- Cuadra el catalogo con lo cargado.
update public.books
set chapter_count = (select count(*) from public.chapters c where c.book_id = 'las-aventuras-de-tom-sawyer'),
    minutes_to_read = 349
where id = 'las-aventuras-de-tom-sawyer';

